16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	
20	import jakarta.persistence.*;
21	import jakarta.validation.constraints.NotEmpty;
22	import jakarta.validation.constraints.Pattern;
23	
24	import java.time.LocalDate;
25	import java.util.*;
26	
27	/**
28	 * Simple JavaBean domain object representing an owner.
29	 *
30	 * @author Ken Krebs
31	 * @author Juergen Hoeller
32	 * @author Sam Brannen
33	 * @author Michael Isvy
34	 */
35	@Entity
36	@Table(name = "owners")
37	public class Owner extends Person {
38	    @Column(name = "address")
39	    @NotEmpty
40	    private String address;
41	
42	    @Column(name = "city")
43	    @NotEmpty
44	    private String city;
45	
46	    @Column(name = "telephone")
47	    @NotEmpty
48	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form: a '+' followed by 8 to 15 digits")
49	    private String telephone;
50	
51	    @Column(name = "email")
52	    private String email;
53	
54	    @Column(name = "postcode")
55	    private String postcode;
56	
57	    @Column(name = "registration_date", columnDefinition = "DATE")
58	    private LocalDate registrationDate;
59	
60	    @Column(name = "customer_code")
61	    private String customerCode;
62	
63	    @Column(name = "household_id")
64	    private String householdId;
65	
66	    @Column(name = "namesake_count")
67	    private Integer namesakeCount;
68	
69	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
70	    private Set<Pet> pets;
71	
72	    /**
73	     * Fixed city-to-region lookup backing {@link #getLocality()}. Any city not listed derives
74	     * locality {@code 'UNKNOWN'}.
75	     */
76	    private static final Map<String, String> CITY_REGION = Map.of(
77	        "Sydney", "NSW",
78	        "Melbourne", "VIC",
79	        "Brisbane", "QLD");
80	
81	    public String getAddress() {
82	        return this.address;
83	    }
84	
85	    public void setAddress(String address) {
86	        this.address = address;
87	    }
88	
89	    public String getCity() {
90	        return this.city;
91	    }
92	
93	    public void setCity(String city) {
94	        this.city = city;
95	    }
96	
97	    public String getTelephone() {
98	        return this.telephone;
99	    }
100	
101	    public void setTelephone(String telephone) {
102	        this.telephone = telephone;
103	    }
104	
105	    public String getEmail() {
106	        return this.email;
107	    }
108	
109	    public void setEmail(String email) {
110	        this.email = email;
111	    }
112	
113	    public String getPostcode() {
114	        return this.postcode;
115	    }
116	
117	    public void setPostcode(String postcode) {
118	        this.postcode = postcode;
119	    }
120	
121	    public LocalDate getRegistrationDate() {
122	        return this.registrationDate;
123	    }
124	
125	    public void setRegistrationDate(LocalDate registrationDate) {
126	        this.registrationDate = registrationDate;
127	    }
128	
129	    public String getCustomerCode() {
130	        return this.customerCode;
131	    }
132	
133	    public void setCustomerCode(String customerCode) {
134	        this.customerCode = customerCode;
135	    }
136	
137	    public String getHouseholdId() {
138	        return this.householdId;
139	    }
140	
141	    public void setHouseholdId(String householdId) {
142	        this.householdId = householdId;
143	    }
144	
145	    public Integer getNamesakeCount() {
146	        return this.namesakeCount;
147	    }
148	
149	    public void setNamesakeCount(Integer namesakeCount) {
150	        this.namesakeCount = namesakeCount;
151	    }
152	
153	    /**
154	     * The owner's name formatted as {@code 'LastName, FirstName'} from the stored names.
155	     */
156	    @Transient
157	    public String getDisplayName() {
158	        return this.getLastName() + ", " + this.getFirstName();
159	    }
160	
161	    /**
162	     * The owner's initials: the upper-cased first letters of the first and last name,
163	     * dot-separated with a trailing dot (e.g. {@code 'J.S.'}).
164	     */
165	    @Transient
166	    public String getInitials() {
167	        return Character.toUpperCase(this.getFirstName().charAt(0)) + "."
168	            + Character.toUpperCase(this.getLastName().charAt(0)) + ".";
169	    }
170	
171	    /**
172	     * The owner's membership number, formatted {@code '<customerCode>-M<YY>'} where {@code YY} is
173	     * the last two digits of the registration date year (e.g. {@code 'SMI-0007-M26'}). Derived from
174	     * the owner's own fields; {@code null} until both the customer code and registration date are set.
175	     */
176	    @Transient
177	    public String getMembershipNumber() {
178	        if (this.customerCode == null || this.registrationDate == null) {
179	            return null;
180	        }
181	        return String.format("%s-M%02d", this.customerCode, this.registrationDate.getYear() % 100);
182	    }
183	
184	    /**
185	     * The owner's numeric membership level, from 1 to 3. It starts at 1, gains 1 when the owner has
186	     * an email address, gains 1 when the owner is unique (namesakeCount is 0), and is capped at 3
187	     * (level 4 is reserved for tenure). The inputs are the owner's own fields.
188	     */
189	    @Transient
190	    public Integer getMembershipLevel() {
191	        int level = 1;
192	        boolean hasEmail = this.email != null && !this.email.isBlank();
193	        if (hasEmail) {
194	            level++;
195	        }
196	        boolean unique = this.namesakeCount != null && this.namesakeCount == 0;
197	        if (unique) {
198	            level++;
199	        }
200	        return Math.min(level, 3);
201	    }
202	
203	    /**
204	     * The owner's locality: the canonical region derived from the city via the fixed city-to-region
205	     * table ({@code Sydney->NSW}, {@code Melbourne->VIC}, {@code Brisbane->QLD}), or {@code 'UNKNOWN'}
206	     * when the city is not in the table.
207	     */
208	    @Transient
209	    public String getLocality() {
210	        return CITY_REGION.getOrDefault(this.city, "UNKNOWN");
211	    }
212	
213	    /**
214	     * The owner's identity key: a single derived value that consolidates all duplicate detection,
215	     * formatted {@code '<normalizedTelephone>|<email or empty>|<householdId or empty>'}. The
216	     * telephone is the stored E.164 value, the email its stored lower-cased form (empty when the
217	     * owner has none), and the household id the stored shared identifier (empty when the owner is
218	     * not part of a shared household). Two owners are duplicates only when their whole identity keys
219	     * are equal; because the telephone is part of the key, two members of the same household with
220	     * different telephones have different identity keys.
221	     */
222	    @Transient
223	    public String getIdentityKey() {
224	        String telephonePart = this.telephone == null ? "" : this.telephone;
225	        String emailPart = this.email == null ? "" : this.email;
226	        String householdPart = this.householdId == null ? "" : this.householdId;
227	        return telephonePart + "|" + emailPart + "|" + householdPart;
228	    }
229	
230	    /**
231	     * The owner's preferred contact channel, derived from the owner's own fields:
232	     * {@code 'EMAIL'} when an email address is present, otherwise {@code 'PHONE'}.
233	     */
234	    @Transient
235	    public String getContactPreference() {
236	        boolean hasEmail = this.email != null && !this.email.isBlank();
237	        return hasEmail ? "EMAIL" : "PHONE";
238	    }
239	
240	    protected Set<Pet> getPetsInternal() {
241	        if (this.pets == null) {
242	            this.pets = new HashSet<>();
243	        }
244	        return this.pets;
245	    }
246	
247	    protected void setPetsInternal(Set<Pet> pets) {
248	        this.pets = pets;
249	    }
250	
251	    public List<Pet> getPets() {
252	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
253	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
254	        return Collections.unmodifiableList(sortedPets);
255	    }
256	
257	    public void setPets(List<Pet> pets) {
258	        this.pets = new HashSet<>(pets);
259	    }
260	
261	    public void addPet(Pet pet) {
262	        getPetsInternal().add(pet);
263	        pet.setOwner(this);
264	    }
265	
266	    /**
267	     * Return the Pet with the given name, or null if none found for this Owner.
268	     *
269	     * @param name to test
270	     * @return true if pet name is already in use
271	     */
272	    public Pet getPet(String name) {
273	        return getPet(name, false);
274	    }
275	
276	    /**
277	     * Return the Pet with the given name, or null if none found for this Owner.
278	     *
279	     * @param name to test
280	     * @return true if pet name is already in use
281	     */
282	    public Pet getPet(String name, boolean ignoreNew) {
283	        name = name.toLowerCase();
284	        for (Pet pet : getPetsInternal()) {
285	            if (!ignoreNew || !pet.isNew()) {
286	                String compName = pet.getName();
287	                compName = compName.toLowerCase();
288	                if (compName.equals(name)) {
289	                    return pet;
290	                }
291	            }
292	        }
293	        return null;
294	    }
295	
296	    public Pet getPet(Integer petId) {
297	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
298	    }
299	
300	    @Override
301	    public String toString() {
302	        return new ToStringCreator(this)
303	
304	            .append("id", this.getId())
305	            .append("new", this.isNew())
306	            .append("lastName", this.getLastName())
307	            .append("firstName", this.getFirstName())
308	            .append("address", this.address)
309	            .append("city", this.city)
310	            .append("telephone", this.telephone)
311	            .toString();
312	    }
313	}
